import{_ as a,c as r,o as t,ag as s}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"F03 — Closures, races and cleanup","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/f03-javascript.md","filePath":"practice/frontend/f03-javascript.md"}'),n={name:"practice/frontend/f03-javascript.md"};function i(o,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="f03-—-closures-races-and-cleanup" tabindex="-1">F03 — Closures, races and cleanup <a class="header-anchor" href="#f03-—-closures-races-and-cleanup" aria-label="Permalink to “F03 — Closures, races and cleanup”">​</a></h1><p><strong>Learner status: outstanding.</strong></p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>F01; execution, lexical scope, identity, promises and browser event propagation. Reuse P-329.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Connect search through a controlled deferred adapter. Define event-time versus current selection semantics; give each route/search one disposable owner.</p><h2 id="observable-acceptance" tabindex="-1">Observable acceptance <a class="header-anchor" href="#observable-acceptance" aria-label="Permalink to “Observable acceptance”">​</a></h2><p>Request A then B; resolve B then A: B remains visible. Repeat with an abort-ignoring adapter and a late rejection. Every promise rejection is observed; after dispose no result/status commits; timers/listeners/controllers are released. Pure transforms leave prior data unchanged.</p><h2 id="failure-cases" tabindex="-1">Failure cases <a class="header-anchor" href="#failure-cases" aria-label="Permalink to “Failure cases”">​</a></h2><p>Reject after replacement, dispose twice, reject during body read, invalid DTO, timeout and account-scope change. A timeout does not prove a remote write was rolled back.</p><h2 id="evidence-to-record" tabindex="-1">Evidence to record <a class="header-anchor" href="#evidence-to-record" aria-label="Permalink to “Evidence to record”">​</a></h2><p>Retain exact schedules, assertions and listener/timer ownership evidence. Predict microtask/task order before running. Demonstrate a removed generation guard failing, then restore it. Link shared Node/CS concepts instead of duplicating implementations.</p><p>Return to <a href="./">the sequence</a> and <a href="./../frontend-project.html">original P-328–P-330 specification</a>. Author verification never completes this stage.</p>',13)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
